package com.pandinila.broadband_management.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="network_metrics", indexes=@Index(name="idx_metric_customer_time", columnList="customer_id,timestamp"))
public class NetworkMetric {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer; @Column(nullable=false) private Instant timestamp=Instant.now();
 private double downloadSpeed, uploadSpeed, latency, packetLoss, jitter, signalStrength, bandwidthUtilization, uptime, downtime, connectionStability;
 public Long getId(){return id;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} public Instant getTimestamp(){return timestamp;} public void setTimestamp(Instant v){timestamp=v;} public double getDownloadSpeed(){return downloadSpeed;} public void setDownloadSpeed(double v){downloadSpeed=v;} public double getUploadSpeed(){return uploadSpeed;} public void setUploadSpeed(double v){uploadSpeed=v;} public double getLatency(){return latency;} public void setLatency(double v){latency=v;} public double getPacketLoss(){return packetLoss;} public void setPacketLoss(double v){packetLoss=v;} public double getJitter(){return jitter;} public void setJitter(double v){jitter=v;} public double getSignalStrength(){return signalStrength;} public void setSignalStrength(double v){signalStrength=v;} public double getBandwidthUtilization(){return bandwidthUtilization;} public void setBandwidthUtilization(double v){bandwidthUtilization=v;} public double getUptime(){return uptime;} public void setUptime(double v){uptime=v;} public double getDowntime(){return downtime;} public void setDowntime(double v){downtime=v;} public double getConnectionStability(){return connectionStability;} public void setConnectionStability(double v){connectionStability=v;}
}
